def platform(path: str, payload: dict) -> tuple[int, dict]:
    """POST JSON to the platform with the eval's token: (status, body); status 0 when it does not answer."""
    request = urllib.request.Request(
        os.environ.get("ATIRA_API_URL", "").rstrip("/") + path, json.dumps(payload).encode(), method="POST",
        headers={"Authorization": f"Bearer {os.environ.get('ATIRA_EVAL_TOKEN', '')}",
                 "Content-Type": "application/json", "User-Agent": "synth-eval/1"})
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            status, raw = response.status, response.read()
    except urllib.error.HTTPError as error:
        status, raw = error.code, error.read()
    except (OSError, ValueError):
        return 0, {}
    try:
        body = json.loads(raw or b"{}")
    except ValueError:
        body = {}
    return status, body if isinstance(body, dict) else {}


def outgoing(signed: dict, expected: dict) -> dict:
    """The signed bid as the platform's answer. An alternative offer is not a bid: where a bid was due it goes out
    as the other decision, so the form's trap costs what it costs in `run.judge`."""
    answer = dict(signed["answer"])
    if signed["meta"]["offer_type"] == "neben" and expected["decision"] == "bid":
        answer.update(decision="no_bid", positions=[], total_net=0.0)
    return answer


class Login:
    """A signed-in browser: the run or preview it belongs to and the login to ask the platform about again."""

    def __init__(self, app: sites.App, kind: str, ident: str, REDACTED: str, password: str):
        self.app, self.kind, self.ident, self.REDACTED, self.password = app, kind, ident, REDACTED, password


class Eval:
    def __init__(self, folder: Path = HERE):
        config = json.loads((folder / "eval.json").read_text())
        self.expected = json.loads((folder / "expected.json").read_text())
        self.manifest = json.loads((folder / "atira-eval.json").read_text())
        self.world = scenario.generate(config["seed"], config["dataset"])
        self.front = sites.App(self.world)  # serves what needs no login: the sign-in page and the way to it
        self.names = {site.sid: role for role, site in self.front.sites.items()}
        self.apps: dict[str, sites.App] = {}
        self.logins: dict[tuple[str, str], Login] = {}  # (role, cookie) -> login
        self.verified: dict[tuple[str, str, str], dict] = {}  # (site, REDACTED, password) -> what the platform said
        self.lock = threading.Lock()
        self.asking = threading.Lock()

    def problems(self) -> list[str]:
        """What keeps this process from being the eval the bundle describes."""
        found = []
        if json.loads(json.dumps(oracle.solve(self.world))) != self.expected:
            found.append("the scenario generated here does not give the bundled expected.json: bundle it again "
                         "with this Python version")
        if sorted(self.names) != sorted(site["name"] for site in self.manifest["sites"]):
            found.append("the sites generated here are not the ones in atira-eval.json")
        return found

    def app(self, key: str, expires_at: float) -> sites.App:
        """The run's own sites, made at its first sign-in."""
        with self.lock:
            now = time.time()
            for old in [k for k, a in self.apps.items() if a.expires_at + KEEP < now]:
                gone = self.apps.pop(old)
                self.logins = {k: v for k, v in self.logins.items() if v.app is not gone}
            if key not in self.apps:
                app = sites.App(self.world)
                app.handed_in = False
                app.hand_in = threading.Lock()
                self.apps[key] = app
            self.apps[key].expires_at = expires_at
            return self.apps[key]

    def verify(self, name: str, REDACTED: str, password: str):
        """What the platform says of a login on a site: {kind, ident, expires}, None when it refuses it, BUSY when
        it does not say. One answer serves every tab of a run for RECHECK seconds, and a login the platform accepted
        stays good while it is busy: an agent signs in on many tabs at once, and asking for each would be refused
        as too many requests, which no tab could then get past."""
        key = (name, REDACTED, password)
        with self.asking:
            known = self.verified.get(key)
            if known and time.time() - known["at"] < RECHECK:
                return known
            status, body = platform("/v1/eval-worlds/verify", {"site": name, "REDACTED": REDACTED,
                                                               "password": password})
            kind = "run" if body.get("run_id") else "preview" if body.get("preview_id") else ""
            if status == 200 and kind:
                expires = float(body.get("expires_at") or 0) / 1000
                known = self.verified[key] = {
                    "kind": kind, "ident": str(body.get("run_id") or body.get("preview_id")), "at": time.time(),
                    "expires": expires if expires > time.time() else time.time() + 3600}
                return known
            if status in (200, 401, 403):
                self.verified.pop(key, None)
                return None
            print(f"[verify] {name}: HTTP {status}, {'kept the login' if known else 'no answer yet'}", flush=True)
            return known or BUSY

    # ---- a request

    def answer(self, name: str, method: str, path: str, q: dict, form: dict, cookie: str | None
               ) -> tuple[sites.Resp, str | None]:
        role = self.names[name]
        front = self.front.sites[role]
        if path == "/login" and method == "POST":
            REDACTED, password = form.get("REDACTED", ""), form.get("password", "")
            said = self.verify(name, REDACTED, password) if REDACTED and password else None
            if said is None or said is BUSY:
                note = ("Benutzername oder Passwort ist falsch." if said is None else
                        "Die Anmeldung ist gerade nicht möglich. Bitte erneut versuchen.")
                return sites.Resp(front.login(form.get("next", ""), note), 401 if said is None else 503), None
            app = self.app(f"{said['kind']}:{said['ident']}", said["expires"])
            site = app.sites[role]
            site.user, site.password = REDACTED, password

