export PATH="$HOME/.local/bin:$PATH"; cd /Users/akshatkhair/Documents/Projects/error404ai_ehl_finals && python3 -I - <<'EOF'
import json, collections
rows = {}
for line in open("experiments/runs.jsonl"):
    line = line.strip()
    if line:
        try: r = json.loads(line)
        except ValueError: continue
        rows[r["id"]] = r
rs = list(rows.values())
print(len(rs), "recorded runs;", collections.Counter(r.get("kind") for r in rs))
def q(r): return (r.get("platform") or {}).get("quality")
def cost(r): return (r.get("platform") or {}).get("cost_usd") or 0
def secs(r): return (r.get("platform") or {}).get("scored_duration_s") or r.get("duration_s") or 0
def cxt(r): return max(cost(r), 0.01) * max(secs(r), 1)
scored = [r for r in rs if q(r) is not None and (r.get("platform") or {}).get("eligible")]
print("eligible scored:", len(scored), " quality 100:", sum(q(r) == 100 for r in scored))
print("quality histogram:", sorted(collections.Counter(round(q(r)) for r in scored).items()))
for kind in ("submission", "test-run"):
    best = sorted([r for r in scored if r.get("kind") == kind], key=lambda r: (-q(r), cxt(r)))[:6]
    print(f"\nbest {kind}s (quality, then cost x time):")
    for r in best:
        print(f"  q {q(r):5} ${cost(r):.4f} {secs(r):6.0f}s cxt {cxt(r):7.1f} {r['id']} {r.get('version')}/{r.get('experiment')} {r.get('commit')} {r.get('started_at','')[:16]} | {(r.get('note') or '')[:70]}")
# by experiment: mean quality where n>=3
by = collections.defaultdict(list)
for r in scored: by[(r.get("version"), r.get("experiment"))].append(r)
print("\nvariants with >=3 runs, by mean quality then mean cost x time:")
out = sorted(by.items(), key=lambda kv: (-sum(map(q, kv[1])) / len(kv[1]), sum(map(cxt, kv[1])) / len(kv[1])))
for (v, e), g in out[:12]:
    if len(g) >= 3:
        print(f"  n={len(g):3} mean q {sum(map(q,g))/len(g):5.1f} at100 {sum(q(r)==100 for r in g):3} mean cxt {sum(map(cxt,g))/len(g):7.1f}  {v}/{e}")
EOF
echo; atira status 2>&1 | sed -n 1,12p; curl -s -A "error404ai-dev/1.0" https://ehl-challenge.atira.ai/challenges/rfq/leaderboard.md | head -22

