for kind in ("submission", "test-run"):
    best = sorted([r for r in scored if r.get("kind") == kind], key=lambda r: (-q(r), cxt(r)))[:6]
    print(f"\nbest {kind}s (quality, then cost x time):")
    for r in best:
        print(f"  q {q(r):5} ${cost(r):.4f} {secs(r):6.0f}s cxt {cxt(r):7.1f} {r['id']} {r.get('version')}/{r.get('experiment')} {r.get('commit')} {r.get('started_at','')[:16]} | {(r.get('note') or '')[:70]}")
# by experiment: mean quality where n>=3
by = collections.defaultdict(list)
for r in scored: by[(r.get("version"), r.get("experiment"))].append(r)
print("\nvariants with >=3 runs, by mean quality then mean cost x time:")
out = sorted(by.items(), key=lambda kv: (-sum(map(q, kv[1])) / len(kv[1]), sum(map(cxt, kv[1])) / len(kv[1])))
for (v, e), g in out[:12]:
    if len(g) >= 3:
        print(f"  n={len(g):3} mean q {sum(map(q,g))/len(g):5.1f} at100 {sum(q(r)==100 for r in g):3} mean cxt {sum(map(cxt,g))/len(g):7.1f}  {v}/{e}")
